// The rep brief is extractive: the prospect's own words, quoted, plus facts inserted by code from the registry and, when
// the organization has a rate group, from the rate file (src/outbound/fact.ts). Nothing in here is generated by a model.
import type { LeadEvent, Normalized, Qualification, Resolution } from './schema';

const METHOD_TEXT: Record<string, string> = {
  curated_domain: 'matched on domain (curated list)', org_domain: 'matched on domain', company_name: 'matched on company name',
  site_title: 'matched on homepage title', nppes: 'matched in NPPES', tld: 'placed by domain ending', inferred: 'inferred from title', crm: 'matched to an account already in the CRM', none: 'not matched',
};

export function orgFacts(res: Resolution): string {
  const f = res.firmographics;
  const bits: string[] = [];
  if (res.accountId?.startsWith('ahrq:')) {
    bits.push('AHRQ health system');
    if (f.hospitals) bits.push(`${f.hospitals} hospitals`);
    if (f.beds) bits.push(`${f.beds.toLocaleString('en-US')} beds`);
    if (f.states?.length) bits.push(f.states.length > 3 ? `${f.states.length} states` : f.states.join('/'));
  } else if (res.accountId?.startsWith('ccn:')) {
    bits.push('standalone hospital (CMS)');
    if (f.cmsType) bits.push(f.cmsType);
    if (f.beds) bits.push(`${f.beds} beds`);
  } else if (res.accountId?.startsWith('payer:')) {
    bits.push(`payer${f.payerKind ? ' (' + f.payerKind + ')' : ''}`);
  } else if (res.accountId?.startsWith('npi:')) {
    bits.push(`provider group, NPI ${f.npi}`);
    if (f.taxonomy) bits.push(f.taxonomy);
  } else if (res.segment !== 'unknown_org') {
    bits.push(res.subsegment ? `${res.segment.replace(/_/g, ' ')}, ${res.subsegment}` : res.segment.replace(/_/g, ' '));
  } else bits.push('organization not identified');
  bits.push(METHOD_TEXT[res.method] ?? res.method);
  return bits.join(', ');
}

/** Prospect-supplied context that is not a free-text message: guide, badge notes, usage. All facts, no prose. */
export function contextFacts(ev: LeadEvent): string | null {
  const c = ev.context as Record<string, any>;
  if (ev.source === 'sample_signup') return `${c.sessions ?? 0} session(s), ${c.searches ?? 0} search(es)${c.markets?.length ? ', markets: ' + c.markets.join(', ') : ''}`;
  if (ev.source === 'guide_download' && c.guide) return `downloaded "${c.guide}"`;
  if (ev.source === 'event_scan' && c.event) return `badge scan at ${c.event}`;
  if (ev.source === 'marketplace' && c.marketplace) return `${c.marketplace} listing inquiry`;
  if (ev.source === 'api_key' && c.product) return `created a ${c.product} developer key`;
  if (ev.source === 'web_intent') return `${(c.visits ?? []).length} page view(s), ${c.visitors ?? '?'} visitor(s)`;
  return null;
}

export function quoteOf(n: Normalized, max = 220): string | null {
  if (!n.message) return null;
  const m = n.message.replace(/\s+/g, ' ');
  return m.length > max ? m.slice(0, max - 1).trimEnd() + '…' : m;
}

export interface Brief {
  person: string; org: string; whyNow: string; quote: string | null;
  /** the organization's own rate from the rate file, one line, or null */
  rates: string | null;
  text: string;
}

export function buildBrief(ev: LeadEvent, n: Normalized, res: Resolution, qual: Qualification, rates: string | null = null): Brief {
  const person = [n.firstName, n.lastName].filter(Boolean).join(' ') || n.email || 'Account-level signal';
  const title = n.title ? `${person}, ${n.title}` : person;
  const org = `${res.accountName ?? n.companyRaw ?? 'Unknown organization'}: ${orgFacts(res)}`;
  const quote = quoteOf(n);
  const ctxFacts = contextFacts(ev);
  const e = qual.rules.evidence;
  const timing = qual.final.sources?.urgency === 'rules' && e?.urgencyCue ? ` ("${e.urgencyCue}"${e.urgencyDate ? `, ${e.urgencyDate}, ${e.urgencyDays} days out` : ''})` : '';
  const whyNow = `${ev.source.replace(/_/g, ' ')}; urgency ${qual.final.urgency.replace(/_/g, ' ')}${timing}; use case ${qual.final.useCase.replace(/_/g, ' ')}`;
  const said = quote ? `They wrote: "${quote}"` : (ctxFacts ? `Activity: ${ctxFacts}` : 'No message.');
  const text = [title, org, ...(rates ? [rates] : []), `Why now: ${whyNow}`, said].join('\n');
  return { person: title, org, whyNow, quote, rates, text };
}
